SELECT EXISTS(
    SELECT 1 FROM source_document
    WHERE tenant_id = #{tenantId}
      AND source_type = 'feishu'
      AND sync_status = 'archived'
      AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.documentKind')) = 'FILE'
      AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.rootDocumentId')) = #{rootDocumentId}
)

SELECT file_doc.* FROM source_document file_doc
WHERE file_doc.tenant_id = #{tenantId}
  AND file_doc.source_type = 'feishu'
  AND file_doc.sync_status <> 'archived'
  AND JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.documentKind')) = 'FILE'
  AND JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.rootDocumentId')) = #{rootDocumentId}
  AND file_doc.id > CAST(#{afterFileDocumentId} AS UNSIGNED)
ORDER BY file_doc.id ASC
LIMIT #{limit}

SELECT file_doc.* FROM source_document file_doc
WHERE file_doc.tenant_id = #{tenantId}
  AND file_doc.source_type = 'feishu'
  AND file_doc.sync_status <> 'archived'
  AND JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.documentKind')) = 'FILE'
  AND JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.rootDocumentId')) = #{rootDocumentId}
  AND file_doc.id > CAST(#{afterFileDocumentId} AS UNSIGNED)


      AND JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.fileIdentityHash')) NOT IN
      #{identityHash}



ORDER BY file_doc.id ASC
LIMIT #{limit}

