UPDATE source_document
SET sync_status = 'archived', parse_status = 'archived', embedding_status = 'archived'
WHERE tenant_id = #{tenantId}
  AND source_type = 'feishu'
  AND sync_status <> 'archived'
  AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.documentKind')) = 'FILE'
  AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.rootDocumentId')) = #{rootDocumentId}


      AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.fileIdentityHash')) NOT IN
      #{identityHash}
